package com.mygo.music;

import android.app.*;
import android.content.*;
import android.content.pm.ActivityInfo;
import android.graphics.*;
import android.media.MediaPlayer;
import android.net.Uri;
import android.os.*;
import android.view.*;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.regex.*;

/** Real window sizes, shared native playback, return gestures and rendered timing/budgets. */
final class ThemeExperienceChecks {
    final Instrumentation test;final Context context;final CompletionChecks helper;final NowPlayingChecks actions;
    ThemeExperienceChecks(Instrumentation test){this.test=test;context=test.getTargetContext();helper=new CompletionChecks(test);actions=new NowPlayingChecks(test);}
    void ui(NowPlayingChecks.Action action)throws Exception{actions.ui(action);}
    void check(boolean yes,String message){NowPlayingChecks.check(yes,message);}
    String shell(String command)throws Exception{try(ParcelFileDescriptor p=test.getUiAutomation().executeShellCommand(command);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(p)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}}
    void shot(String name)throws Exception{test.waitForIdleSync();SystemClock.sleep(90);Bitmap b=test.getUiAutomation().takeScreenshot();check(b!=null,"native screenshot missing");File folder=new File(context.getExternalFilesDir(null),"qa/theme-experience");folder.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(folder,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}finally{b.recycle();}}
    Bitmap pixels(View view)throws Exception{Bitmap[] result={null};ui(()->{result[0]=Bitmap.createBitmap(view.getWidth(),view.getHeight(),Bitmap.Config.ARGB_8888);view.draw(new Canvas(result[0]));});return result[0];}
    Bitmap background(ThemedPlayerDialog page,long position)throws Exception{Bitmap[] result={null};ui(()->{result[0]=Bitmap.createBitmap(320,180,Bitmap.Config.ARGB_8888);page.backdrop.setBounds(0,0,320,180);page.backdrop.state(position,true,false);page.backdrop.draw(new Canvas(result[0]));});return result[0];}
    void visible(View view,String label){Rect r=new Rect();check(view.getGlobalVisibleRect(r)&&r.width()==view.getWidth()&&r.height()==view.getHeight(),"clipped "+label);}
    void geometry(ThemedPlayerDialog p,boolean landscape){
        for(View v:new View[]{p.play,p.previous,p.next,p.shuffle,p.repeat,p.collapse}){visible(v,p.theme()+" "+v.getContentDescription());check(v.getWidth()>=p.dp(48)&&v.getHeight()>=p.dp(48),"small transport "+p.theme());}
        if(!p.theme().equals("immersive")){visible(p.artworkView,"artwork "+p.theme());check(p.artworkView.getWidth()>p.dp(48)&&p.artworkView.getHeight()>p.dp(48),"missing compact artwork "+p.theme());}
        if(p.stage.getVisibility()==View.VISIBLE){visible(p.stage,"lyrics "+p.theme());Rect text=new Rect(p.stage.getLeft(),p.stage.getTop(),p.stage.getRight(),p.stage.getBottom()),controls=new Rect(p.controls.getLeft(),p.controls.getTop(),p.controls.getRight(),p.controls.getBottom());check(!Rect.intersects(text,controls),"lyrics overlap controls "+p.theme());}
        if(landscape&&p.theme().equals("professional")&&p.body.getWidth()>=p.dp(580)){check(p.controls.getRight()<p.stage.getLeft(),"professional transport did not move into left column");check(p.stage.getHeight()>=p.dp(140),"professional lyrics still compressed into one short strip");}
    }
    void rendered(ThemedPlayerDialog p)throws Exception{
        Bitmap screen=test.getUiAutomation().takeScreenshot(),expected=pixels(p.artworkView);int[] location=new int[2];ui(()->p.artworkView.getLocationOnScreen(location));int x=p.artworkView.getWidth()/2,y=p.artworkView.getHeight()/2,a=expected.getPixel(x,y),b=screen.getPixel(location[0]+x,location[1]+y);check(Math.abs(Color.red(a)-Color.red(b))<32&&Math.abs(Color.green(a)-Color.green(b))<32&&Math.abs(Color.blue(a)-Color.blue(b))<32,"visible artwork pixels missing at "+screen.getWidth()+"x"+screen.getHeight());expected.recycle();ui(()->p.stage.getLocationOnScreen(location));int bright=0;for(int yy=0;yy<p.stage.getHeight();yy+=2)for(int xx=0;xx<p.stage.getWidth();xx+=2){int color=screen.getPixel(location[0]+xx,location[1]+yy);if(Color.red(color)>110&&Color.green(color)>110&&Color.blue(color)>120)bright++;}screen.recycle();check(bright>12,"visible professional lyric pixels missing at "+p.root.getWidth()+"x"+p.root.getHeight());
    }
    void run()throws Exception{
        SharedPreferences prefs=context.getSharedPreferences("library",0);Map<String,?> original=new HashMap<>(prefs.getAll());String priorSize=shell("wm size");Matcher override=Pattern.compile("Override size: (\\d+x\\d+)").matcher(priorSize);String restoreSize=override.find()?"wm size "+override.group(1):"wm size reset";
        prefs.edit().putBoolean("player_remember_theme",true).putString("player_theme","dynamic").putBoolean("auto_cache",false).remove("selected_source").putFloat("play_speed",1).commit();
        MainActivity activity=(MainActivity)test.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));PlaybackService[] connected={null};helper.await(()->{connected[0]=(PlaybackService)FullPortChecks.field(activity,"playbackService");return connected[0]!=null;},"matrix service missing");PlaybackService service=connected[0];ThemedPlayerDialog[] page={null};
        File wave=new File(context.getCacheDir(),"theme-matrix.wav"),art=new File(context.getCacheDir(),"theme-matrix-cover.png");try(FileOutputStream out=new FileOutputStream(wave)){out.write(BackgroundPlaybackChecks.wav(180000));}Bitmap cover=Bitmap.createBitmap(512,512,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(cover);Paint paint=new Paint();paint.setShader(new LinearGradient(0,0,512,512,0xffd6a98d,0xff356a88,Shader.TileMode.CLAMP));canvas.drawPaint(paint);try(FileOutputStream out=new FileOutputStream(art)){cover.compress(Bitmap.CompressFormat.PNG,100,out);}cover.recycle();String uri=Uri.fromFile(wave).toString();
        String wordSource=new JSONObject().put("lines",new JSONArray().put(new JSONObject().put("start",0).put("end",6000).put("words",new JSONArray().put(new JSONObject().put("text","海风 ").put("start",0).put("end",3000)).put(new JSONObject().put("text","café 👩🏽‍🎤").put("start",3000).put("end",6000))).put("translation","The wind carries our song").put("romanization","hai feng" )).put(new JSONObject().put("start",6000).put("end",12000).put("words",new JSONArray().put(new JSONObject().put("text","مرحبا 世界").put("start",6000).put("end",12000))))).toString();LyricsTimeline words=LyricsTimeline.parse(wordSource);
        try{
            JSONObject track=new JSONObject().put("name","海风与星光").put("artists",new JSONArray().put(new JSONObject().put("name","MyGo 原生体验验证"))).put("album",new JSONObject().put("name","主题布局与时间轴").put("imageUrl",art.toURI().toString()));JSONArray queue=new JSONArray().put(new JSONObject().put("uri",uri).put("title","海风与星光").put("track",track));
            ui(()->{((Map<String,String>)FullPortChecks.field(activity,"localLyrics")).put(uri,wordSource);service.clearQueue();PlaybackService.startQueue(context,queue,0,0,61,false,false,"high");});helper.await(()->service.snapshot().playing&&service.snapshot().position>100,"matrix audio clock did not start");ui(()->{NowPlayingChecks.invoke(activity,"showNowPlaying");page[0]=(ThemedPlayerDialog)FullPortChecks.field(activity,"themedPlayer");});helper.await(()->page[0]!=null&&page[0].isShowing()&&page[0].host.artwork(uri)!=null&&page[0].stage.timeline().wordTimed&&!page[0].stage.timeline().estimatedWordTiming,"matrix page/art/source timing missing");MediaPlayer core=service.snapshot().player;long generation=service.snapshot().generation;
            for(int[] size:new int[][]{{640,320},{640,360},{480,270},{1280,800},{320,640}}){boolean landscape=size[0]>size[1];ui(()->activity.setRequestedOrientation(landscape?ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE:ActivityInfo.SCREEN_ORIENTATION_PORTRAIT));shell("wm size "+size[0]+"x"+size[1]);helper.await(()->page[0].root.getWidth()==size[0]&&page[0].root.getHeight()==size[1],"window did not reach "+size[0]+"x"+size[1]+" actual="+page[0].root.getWidth()+"x"+page[0].root.getHeight());SystemClock.sleep(350);test.waitForIdleSync();
                for(String id:PlayerThemes.IDS){ui(()->page[0].setTheme(id,true));test.waitForIdleSync();ui(()->{geometry(page[0],landscape);check(page[0].stage.timeline().wordTimed&&!page[0].stage.timeline().estimatedWordTiming,"theme/size lost the shared source timeline");});check(service.snapshot().player==core&&service.snapshot().generation==generation&&service.queueSnapshot().toString().equals(queue.toString()),"size/theme replaced player or queue");shot(size[0]+"x"+size[1]+"-"+id);if(id.equals("professional"))rendered(page[0]);}
            }
            ui(()->activity.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE));shell("wm size 640x360");helper.await(()->page[0].root.getWidth()==640&&page[0].root.getHeight()==360,"landscape test restore missing");
            ui(()->{page[0].setTheme("professional",true);((ViewGroup)page[0].tabs).getChildAt(2).performClick();});test.waitForIdleSync();ui(()->page[0].artworkView.performClick());helper.await(()->page[0].theme().equals("immersive"),"cover tap did not enter immersive lyrics");check(prefs.getString("player_theme","").equals("professional"),"temporary lyrics replaced remembered theme");test.getUiAutomation().performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_BACK);helper.await(()->page[0].isShowing()&&page[0].theme().equals("professional")&&page[0].tab.equals("info"),"Back did not restore originating theme/pane");ui(()->page[0].setTheme("dynamic",true));test.waitForIdleSync();ui(()->page[0].lyrics.performClick());helper.await(()->page[0].theme().equals("immersive"),"lyric shortcut did not enter immersive mode");ui(()->page[0].collapse.performClick());check(page[0].theme().equals("dynamic"),"collapse did not restore the theme");
            ui(()->{page[0].setTheme("immersive",true);page[0].setTimeline(words);service.pause();service.seek(500);});helper.await(()->!service.snapshot().playing&&Math.abs(service.snapshot().position-500)<180,"pause/seek baseline failed");check(page[0].heading.getText().toString().contains("音源逐字时间"),"source word precision not visible");Bitmap paused=pixels(page[0].stage);SystemClock.sleep(160);Bitmap still=pixels(page[0].stage);check(paused.sameAs(still),"paused word pixels kept animating");still.recycle();ui(()->service.seek(1500));helper.await(()->Math.abs(service.snapshot().position-1500)<180,"backward/forward clock seek failed");Bitmap advanced=pixels(page[0].stage);check(!paused.sameAs(advanced),"native seek did not update word pixels");paused.recycle();advanced.recycle();
            ui(()->page[0].setTimeline(LyricsTimeline.parse("[00:00.00]只有行时间\n[00:05.00]估算逐字效果")));check(page[0].heading.getText().toString().contains("估算"),"estimated timing not disclosed on lyric page");shot("precision-estimated");ui(()->page[0].setTimeline(LyricsTimeline.parse("纯文本歌词\n没有演唱时间")));check(page[0].heading.getText().toString().contains("纯文本")&&!page[0].stage.timeline().timed&&!page[0].stage.timeline().wordTimed,"plain text acquired invented timing");
            ui(()->{page[0].setTheme("dynamic",true);prefs.edit().putInt(PlayerThemes.key("dynamic","blur"),0).putInt(PlayerThemes.key("dynamic","background_mode"),0).commit();PlaybackRetryChecks.invoke(page[0],"themeSettings",new Class<?>[]{});});SourcePlaylistUiChecks.click(test,"低性能模式");shot("low-performance-settings");test.getUiAutomation().performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_BACK);helper.await(()->prefs.getBoolean(PlayerThemes.key("dynamic","low_performance"),false)&&(Boolean)FullPortChecks.field(page[0],"lowPerformance"),"low performance UI did not apply");Bitmap lowA=background(page[0],1000),lowB=background(page[0],15000);check(lowA.sameAs(lowB),"low performance did not freeze environmental motion");lowA.recycle();lowB.recycle();Bitmap texture=(Bitmap)FullPortChecks.field(page[0].backdrop,"texture");check(texture!=null&&Math.max(texture.getWidth(),texture.getHeight())<=256,"low performance texture budget was ignored");
            ui(()->{page[0].setTheme("minimal",true);check(!(Boolean)FullPortChecks.field(page[0],"lowPerformance"),"low performance leaked into another theme");page[0].setTheme("dynamic",true);service.resume();});int start=service.snapshot().position;helper.await(()->service.snapshot().position>start+200,"low performance stalled native audio");ui(()->{page[0].dismiss();NowPlayingChecks.invoke(activity,"showNowPlaying");page[0]=(ThemedPlayerDialog)FullPortChecks.field(activity,"themedPlayer");});helper.await(()->page[0].theme().equals("dynamic")&&(Boolean)FullPortChecks.field(page[0],"lowPerformance"),"low performance did not survive reopen");check(service.snapshot().player==core&&service.snapshot().generation==generation,"return/settings/reopen replaced native player");shot("low-performance-dynamic");
            System.out.println("MYGO_THEME_EXPERIENCE_OK scenes=10 sizes=640x320,640x360,480x270,1280x800,320x640 temporaryLyricsReturn=true sourcePrecision=true pausedPixels=true seekPixels=true lowPerformancePixels=true textureBudget=256 largeCanvasPixels=true sharedPlayer=true");
        }finally{ui(()->{if(page[0]!=null)page[0].dismiss();service.clearQueue();ArrayList<Uri> tracks=(ArrayList<Uri>)FullPortChecks.field(activity,"tracks");ArrayList<String> names=(ArrayList<String>)FullPortChecks.field(activity,"names");int at=tracks.indexOf(Uri.parse(uri));if(at>=0){tracks.remove(at);names.remove(at);}PlaybackRetryChecks.invoke(activity,"saveLibrary",new Class<?>[]{});activity.finish();});shell(restoreSize);wave.delete();art.delete();new TurntableLyricsChecks(test).restore(prefs,original);}
    }
}
